import datetime, os

# Rotate through original short-form history/science mysteries by UTC day of year.
stories = [
("The Mary Celeste", "In 1872, the ship Mary Celeste was found drifting in the Atlantic with its crew missing. Much of its cargo remained, and there was no clear sign of a struggle. The lifeboat was gone. Investigators proposed several explanations, but none has been proven. The crew's fate remains one of maritime history's enduring mysteries.", "Mary Celeste ship;historic sailing ship;Atlantic Ocean historical map"),
("The Voynich Manuscript", "The Voynich Manuscript is a centuries-old illustrated book written in a script that has resisted convincing translation. Its pages contain unfamiliar plants, diagrams, and strange scenes. Researchers have suggested ciphers and invented languages, but no interpretation has won broad acceptance. The book is real; what its text means remains unresolved.", "Voynich manuscript;medieval manuscript botanical illustration;medieval manuscript"),
("The Antikythera Mechanism", "A Greek shipwreck yielded a corroded device packed with interlocking gears. Studies revealed that it could model astronomical cycles and predict celestial events. Built more than two thousand years ago, it is often described as an ancient mechanical calculator. Its sophistication changed historians' understanding of technology in the ancient world.", "Antikythera mechanism;ancient Greek shipwreck;ancient Greek astronomy"),
("The Nazca Lines", "Across Peru's Nazca Desert, enormous lines and figures were made by removing dark surface stones to reveal lighter ground. Some form animals and geometric patterns best seen from above. Archaeologists have linked them to ritual landscapes and water-related beliefs, but their exact purposes are still debated.", "Nazca Lines Peru;Nazca geoglyph hummingbird;Peru desert aerial"),
("The Dyatlov Pass Incident", "In 1959, nine hikers died during an expedition in Russia's Ural Mountains. Their abandoned campsite sparked decades of speculation. Modern investigations support natural explanations involving severe weather and a possible snow slab, though details remain debated. The case shows how incomplete evidence can turn tragedy into legend.", "Dyatlov Pass Ural Mountains;Ural Mountains winter;Soviet hiking expedition archive"),
("The Franklin Expedition", "In 1845, two British ships sailed into the Arctic seeking the Northwest Passage. Neither returned. Later searches found abandoned equipment and records, and the wrecks were located much later. Evidence points to harsh ice, starvation, and illness, but many details of the final months remain uncertain.", "HMS Erebus Arctic expedition;Franklin expedition historical map;Arctic ice ship"),
("The Tunguska Event", "In 1908, a huge explosion flattened trees across a remote region of Siberia, yet investigators found no confirmed impact crater. The leading explanation is that a small asteroid or comet fragment exploded in the atmosphere. The event shows how an object from space can cause enormous damage without leaving a typical crater.", "Tunguska event Siberia;Siberian taiga forest;meteor atmospheric explosion"),
("The Dancing Plague of 1518", "In Strasbourg in 1518, historical accounts describe people dancing uncontrollably for days. Historians still debate what caused the episode, with explanations ranging from social stress to illness. Popular retellings sometimes exaggerate details, so surviving records should be treated carefully rather than as a fully solved medical mystery.", "Strasbourg 16th century engraving;medieval dancing plague illustration;Holy Roman Empire historical map"),
("The Phaistos Disc", "Found on Crete in 1908, the Phaistos Disc carries symbols pressed into clay in a spiral pattern. Its signs have not been convincingly deciphered. Some researchers question whether it represents a writing system at all. Until more comparable evidence is found, the disc remains one of archaeology's most intriguing puzzles.", "Phaistos Disc;Minoan civilization Crete;ancient Crete archaeological site"),
("The Oak Island Mystery", "Oak Island in Nova Scotia has attracted treasure hunters for generations because of reports of unusual shafts and underground structures. Searches have uncovered artifacts, but a buried treasure has not been conclusively proven. The island's story shows how uncertain clues can inspire centuries of exploration and speculation.", "Oak Island Nova Scotia;Nova Scotia coastline;historic treasure map"),
("The Wow! Signal", "In 1977, a radio telescope in Ohio recorded a strong signal from space that lasted just over a minute. An astronomer circled the printout and wrote Wow! beside it. Follow-up searches never found a confirmed repeat. The signal remains unexplained, but there is no proof it came from extraterrestrial intelligence.", "Big Ear radio telescope;radio telescope observatory;star field"),
("The Lost Colony of Roanoke", "In 1587, English settlers established a colony on Roanoke Island. When a supply ship returned years later, the settlement was deserted. The word CROATOAN had been carved into a post, but no definitive record explains what happened. Some colonists may have joined nearby Indigenous communities. The settlement's fate remains uncertain.", "Roanoke Island historical map;historic map North Carolina;old sailing ship"),
("The London Beer Flood", "In 1814, a huge vat at a London brewery ruptured, releasing a wave of beer into nearby streets. The flood damaged homes and killed eight people. The event sounds unbelievable, but it was documented in contemporary reports. It was a strange historical disaster caused by industrial equipment failing.", "historic London brewery;19th century London street engraving;old beer brewery barrels"),
("The Bloop Sound", "In 1997, underwater microphones recorded an unusually powerful low-frequency sound in the Pacific. It inspired stories about unknown sea creatures. Later analysis suggested the sound was consistent with ice-related activity, such as cracking icebergs. It remains an example of how limited data can invite dramatic explanations.", "Antarctic iceberg;underwater hydrophone;Southern Ocean ice"),
("Why Businesses Track Cash Flow", "A business can look profitable on paper and still run out of cash. Cash flow tracks when money actually enters and leaves the business, including customer payments, rent, wages, and suppliers. Owners watch it closely because bills have due dates even when sales are strong. Revenue matters, but timing can decide whether a business survives.", "small business cash flow accounting;shop owner bookkeeping;business financial spreadsheet"),
("The Hidden Cost of Inventory", "Stock sitting on a shelf is not free. A business has already paid for the goods, and may also pay for storage, insurance, and handling. Too much inventory ties up cash, while too little can mean lost sales. Smart inventory management balances availability with the real cost of keeping products unsold.", "warehouse inventory shelves;small business stockroom;inventory spreadsheet"),
("Why Companies Build Brands", "A brand is more than a logo. It is the set of expectations customers connect with a company: quality, reliability, service, and identity. When customers recognize and trust a brand, they may be more willing to return or recommend it. Building that trust takes consistency over time, not just a clever advertising campaign.", "brand identity packaging design;small business storefront;marketing team meeting"),
("What Is a Business Moat?", "Investors use the term economic moat for an advantage that helps a company defend itself from competitors. It might be a trusted brand, lower costs, network effects, or switching costs that make customers stay. A moat is never permanent by default: technology, regulation, and changing customer habits can weaken even a strong advantage.", "modern factory production line;technology network concept;business strategy meeting"),
("The Freemium Business Model", "Some apps offer a useful free version and charge for advanced features. This is called freemium. The challenge is balance: the free product must deliver real value, while paid features must solve a meaningful extra problem. If too few users upgrade, the business may struggle to cover support, development, and infrastructure costs.", "mobile app subscription screen;software product team;digital business dashboard"),
("Why Small Businesses Need Unit Economics", "Unit economics asks whether one sale or one customer can make financial sense. A business compares the revenue from a customer with the direct costs of serving them and the cost of acquiring them. Fast growth can hide a weak model if every new customer loses money. Understanding the numbers helps owners improve pricing and operations.", "business owner calculator invoices;small business analytics dashboard;online shop packing orders"),
("The Power of Compound Growth", "Compound growth means gains can build on earlier gains over time. It appears in savings, reinvested profits, and businesses that steadily improve customer retention. The effect depends on time and the rate of growth, and it works in reverse with compounding debt or fees. It is a mathematical concept, not a promise of investment returns.", "compound growth chart notebook;financial planning calculator;long term savings graph"),
("How Subscription Businesses Earn", "Subscription businesses charge customers repeatedly for continued access to a product or service. Predictable recurring revenue can make planning easier, but only when customers keep finding value. Churn, the rate customers cancel, can quietly undermine growth. A healthy subscription business measures retention alongside new sign-ups, rather than celebrating sign-ups alone.", "subscription analytics dashboard;software as a service team;customer retention chart"),
("What Makes a Good Price?", "Pricing is not simply adding a percentage to cost. Businesses also consider customer value, competitors, demand, positioning, and how sensitive buyers are to changes. A price that is too low can damage margins or make quality seem doubtful; one that is too high may reduce sales. Good pricing is tested against real customer behavior.", "product pricing tags small shop;retail owner calculator;market stall products"),
("Why Businesses Use Break-Even Analysis", "The break-even point is where total revenue equals total costs, so the business has neither profit nor loss. Owners estimate fixed costs like rent, then compare them with the contribution each sale makes after variable costs. The calculation helps answer how many units must be sold before a product begins to earn profit.", "business calculator financial planning;small factory production;accounting spreadsheet"),
("Customer Acquisition Cost Explained", "Customer acquisition cost, often called CAC, estimates how much a business spends to win one new customer. It can include advertising, sales labor, and promotional offers. CAC becomes more useful when compared with customer lifetime value and retention. A campaign that brings many sign-ups may still be unprofitable if customers leave quickly.", "digital marketing analytics dashboard;online advertising campaign laptop;marketing team planning"),
("Why Companies Diversify Revenue", "A company that depends on one customer, product, or sales channel can be vulnerable when that source weakens. Diversifying revenue may reduce that dependence, but adding too many products can spread a small team too thin. The goal is not variety for its own sake; it is building complementary sources of income that the business can manage well.", "small business product range;entrepreneur planning notebook;multiple retail products"),
("The Difference Between Revenue and Profit", "Revenue is the money a business earns from sales before expenses are deducted. Profit is what remains after relevant costs. A company can report impressive revenue while making little or no profit if costs are high. That is why sales figures alone do not tell the full story of a business's financial health.", "business financial statements;shop owner counting sales;profit and loss spreadsheet"),
("Why Customer Retention Matters", "Finding new customers often takes marketing and sales effort, while keeping existing customers depends on continued value and service. Retention can support repeat purchases and recommendations, but it should be measured rather than assumed. Businesses study why customers leave, then improve the product or experience instead of relying only on more advertising.", "customer service team office;loyalty program retail;customer feedback laptop"),
]
history_count = 14
channel = os.environ.get("CHANNEL_NAME", "history").strip().lower()
if channel not in ("history", "business"):
    raise SystemExit("CHANNEL_NAME must be history or business")
channel_stories = stories[:history_count] if channel == "history" else stories[history_count:]

# Select by workflow run number, not calendar day. Manual runs on the same day
# must produce different scripts. Fall back to UTC day only for local execution.
run_number = os.environ.get("GITHUB_RUN_NUMBER", "").strip()
if run_number.isdigit() and int(run_number) > 0:
    rotation_index = (int(run_number) - 1) % len(channel_stories)
    rotation_source = "workflow run " + run_number
else:
    day = datetime.datetime.now(datetime.timezone.utc).timetuple().tm_yday
    rotation_index = (day - 1) % len(channel_stories)
    rotation_source = "UTC day fallback"

title, video_script, image_searches = channel_stories[rotation_index]
with open(os.environ["GITHUB_ENV"], "a", encoding="utf-8") as env:
    env.write("CHANNEL_NAME=" + channel + "\n")
    env.write("STORY_TOPIC=" + title + "\n")
    env.write("IMAGE_SEARCHES=" + image_searches + "\n")
    env.write("VIDEO_SCRIPT<<STORY_SCRIPT_EOF\n")
    env.write(video_script + "\n")
    env.write("STORY_SCRIPT_EOF\n")
print("Today's channel: " + channel)
print("Today's topic: " + title)
print("Topic rotation: " + str(rotation_index + 1) + "/" + str(len(channel_stories)))
print("Rotation source: " + rotation_source)
print("Script characters: " + str(len(video_script)))
